-- Run this after schema.sql in the Supabase SQL Editor.
-- This seed matches the local jewelry-001.webp through jewelry-300.webp files. The temporary PKR prices are 100x the previous USD amounts; replace these placeholders before taking real orders.
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  price_paisa = excluded.price_paisa,
  image_path = excluded.image_path,
  image_alt = excluded.image_alt,
  badge = excluded.badge,
  is_active = excluded.is_active;

select setval(
  pg_get_serial_sequence('public.products', 'id'),
  (select max(id) from public.products),
  true
);

select count(*) as active_products from public.products where is_active = true;
